// Loads the textures extracted from the reference sheet and the GLB models
// generated by tools/build_models.py.
import * as THREE from 'three';
import { GLTFLoader } from 'three/addons/loaders/GLTFLoader.js';

export const A = { tex: {}, models: {} };

const TEXTURES = {
  cable_cat6: { srgb: true, wrap: true },
  cable_fiber: { srgb: true, wrap: true },
  cable_terminal: { srgb: true, wrap: true },
  cable_hv: { srgb: true, wrap: true },
  cable_coax: { srgb: true, wrap: true },
  rack_front: { srgb: true, wrap: true },
  rack_emissive: { srgb: true, wrap: true },
  floor_grid: { srgb: true, wrap: true },
  fx_sparks_a: { srgb: true },
  fx_sparks_b: { srgb: true },
  icon_warning: { srgb: true },
};

const MODELS = ['rj45', 'fiber_sc', 'terminal_fork', 'coax_f', 'hv_end', 'firewall', 'packet', 'cut_lan', 'cut_fiber', 'cut_copper'];

export async function loadAssets(renderer, onProgress = () => {}) {
  const total = Object.keys(TEXTURES).length + MODELS.length;
  let done = 0;
  const tick = (label) => onProgress(++done / total, label);
  const maxAniso = renderer.capabilities.getMaxAnisotropy();

  const texLoader = new THREE.TextureLoader();
  const gltfLoader = new GLTFLoader();

  const texJobs = Object.entries(TEXTURES).map(async ([name, o]) => {
    const t = await texLoader.loadAsync(`assets/textures/${name}.png`);
    if (o.srgb) t.colorSpace = THREE.SRGBColorSpace;
    if (o.wrap) t.wrapS = t.wrapT = THREE.RepeatWrapping;
    t.anisotropy = Math.min(8, maxAniso);
    A.tex[name] = t;
    tick(`texture ${name}.png`);
  });

  const modelJobs = MODELS.map(async (name) => {
    const g = await loadModel(gltfLoader, name);
    g.scene.traverse((o) => {
      if (o.isMesh) {
        o.castShadow = false;
        o.receiveShadow = false;
        if (o.material.transparent) o.material.depthWrite = false;
      }
    });
    A.models[name] = g.scene;
    tick(`model ${name}.glb`);
  });

  await Promise.all([...texJobs, ...modelJobs]);
  return A;
}

/** Load assets/models/<name>.glb; hosts that can't serve .glb get a
 *  base64-wrapped copy (<name>.glb.json, {"glb": "..."}) instead. */
async function loadModel(loader, name) {
  const url = `assets/models/${name}.glb`;
  let buf;
  const res = await fetch(url).catch(() => null);
  if (res && res.ok) buf = await res.arrayBuffer();
  else {
    const j = await (await fetch(`${url}.json`)).json();
    buf = Uint8Array.from(atob(j.glb), (c) => c.charCodeAt(0)).buffer;
  }
  return loader.parseAsync(buf, 'assets/models/');
}

/** Clone a model; any material named "boot" is swapped for `bootMat`. */
export function cloneModel(name, bootMat = null) {
  const src = A.models[name];
  const c = src.clone(true);
  if (bootMat) {
    c.traverse((o) => {
      if (o.isMesh && o.material.name === 'boot') o.material = bootMat;
    });
  }
  return c;
}
